// MsgServer is the server API for Msg service.
// All implementations must embed UnimplementedMsgServer
// for forward compatibility.
//
// Msg defines the Msg service.
type MsgServer interface {
	// Commit creates a commitment for name registration using commit-reveal
	// scheme. Stores hash commitment that can be revealed later to prevent
	// front-running.
	Commit(context.Context, *MsgCommit) (*MsgCommitResponse, error)
	// Reveal completes name registration by validating revealed name matches
	// commitment hash. Mints Name NFT, charges valuation fee, and creates reverse
	// mapping for resolution.
	Reveal(context.Context, *MsgReveal) (*MsgRevealResponse, error)
	// SetValuation updates the self-valuation of an NFT, charging Harberger tax
	// on increases. Fee goes to community pool or class owner based on governance
	// status.
	SetValuation(context.Context, *MsgSetValuation) (*MsgSetValuationResponse, error)
	// Renew extends valuation expiry by charging proportional annual fee.
	// Fee is paid to the NFT class owner.
	Renew(context.Context, *MsgRenew) (*MsgRenewResponse, error)
	// PlaceBid places or outbids on a listed NFT, escrowing funds until
	// acceptance or expiry. First bids must meet/exceed valuation; subsequent
	// bids require minimum increase percentage.
	PlaceBid(context.Context, *MsgPlaceBid) (*MsgPlaceBidResponse, error)
	// AcceptBid accepts current active bid, transferring NFT ownership and
	// releasing escrowed funds. Updates NFT valuation to accepted bid amount and
	// clears bid state.
	AcceptBid(context.Context, *MsgAcceptBid) (*MsgAcceptBidResponse, error)
	// RejectBid rejects current bid and sets new valuation, charging rejection
	// fee. Fee routing: to NFT class owner for user-controlled classes, to
	// community pool for governance-controlled classes. Refunds the rejected
	// bidder's escrowed bid amount back to them.
	RejectBid(context.Context, *MsgRejectBid) (*MsgRejectBidResponse, error)
	// ClaimBid allows bidder to claim NFT after bid timeout expires without
	// acceptance. Transfers escrowed bid to previous owner and NFT ownership to
	// bidder.
	ClaimBid(context.Context, *MsgClaimBid) (*MsgClaimBidResponse, error)
	SetDestination(context.Context, *MsgSetDestination) (*MsgSetDestinationResponse, error)
	// SetNameMetadata allows the owner of a name (NFT in nameservice.dys) to set
	// the metadata string for that name. Only the owner can call this.
	SetNameMetadata(context.Context, *MsgSetNameMetadata) (*MsgSetNameMetadataResponse, error)
	SetNFTMetadata(context.Context, *MsgSetNFTMetadata) (*MsgSetNFTMetadataResponse, error)
	SetNFTClassExtraData(context.Context, *MsgSetNFTClassExtraData) (*MsgSetNFTClassExtraDataResponse, error)
	// SetNFTClassAlwaysListed sets the always_listed flag for an NFT class
	SetNFTClassAlwaysListed(context.Context, *MsgSetNFTClassAlwaysListed) (*MsgSetNFTClassAlwaysListedResponse, error)
	// Set per-class valuation fee percent and period
	SetNFTClassValuationFeePct(context.Context, *MsgSetNFTClassValuationFeePct) (*MsgSetNFTClassValuationFeePctResponse, error)
	SetNFTClassValuationPeriod(context.Context, *MsgSetNFTClassValuationPeriod) (*MsgSetNFTClassValuationPeriodResponse, error)
	// Per-class bidding params setters
	SetNFTClassBidTimeout(context.Context, *MsgSetNFTClassBidTimeout) (*MsgSetNFTClassBidTimeoutResponse, error)
	SetNFTClassAllowedDenoms(context.Context, *MsgSetNFTClassAllowedDenoms) (*MsgSetNFTClassAllowedDenomsResponse, error)
	SetNFTClassRejectBidValuationFeePercent(context.Context, *MsgSetNFTClassRejectBidValuationFeePercent) (*MsgSetNFTClassRejectBidValuationFeePercentResponse, error)
	SetNFTClassMinimumBidPercentIncrease(context.Context, *MsgSetNFTClassMinimumBidPercentIncrease) (*MsgSetNFTClassMinimumBidPercentIncreaseResponse, error)
	// SetListed sets the listed status for a specific NFT
	SetListed(context.Context, *MsgSetListed) (*MsgSetListedResponse, error)
	UpdateParams(context.Context, *MsgUpdateParams) (*MsgUpdateParamsResponse, error)
	MintCoins(context.Context, *MsgMintCoins) (*MsgMintCoinsResponse, error)
	BurnCoins(context.Context, *MsgBurnCoins) (*MsgBurnCoinsResponse, error)
	SetDenomMetadata(context.Context, *MsgSetDenomMetadata) (*MsgSetDenomMetadataResponse, error)
	// Allow the denom root owner to set description only
	SetDenomDescription(context.Context, *MsgSetDenomDescription) (*MsgSetDenomDescriptionResponse, error)
	// Allow the denom root owner to set URI and URI hash only
	SetDenomURI(context.Context, *MsgSetDenomURI) (*MsgSetDenomURIResponse, error)
	SaveClass(context.Context, *MsgSaveClass) (*MsgSaveClassResponse, error)
	// DeleteClass removes an NFT class. Only allowed if the class has no NFTs.
	DeleteClass(context.Context, *MsgDeleteClass) (*MsgDeleteClassResponse, error)
	MintNFT(context.Context, *MsgMintNFT) (*MsgMintNFTResponse, error)
	BurnNFT(context.Context, *MsgBurnNFT) (*MsgBurnNFTResponse, error)
	MoveCoins(context.Context, *MsgMoveCoins) (*MsgMoveCoinsResponse, error)
	MoveNft(context.Context, *MsgMoveNft) (*MsgMoveNftResponse, error)
	CreateExternalName(context.Context, *MsgCreateExternalName) (*MsgCreateExternalNameResponse, error)
	mustEmbedUnimplementedMsgServer()
}

